 private JPanel card(String n,String title,String desc,Runnable action){JPanel p=new JPanel(new BorderLayout(12,4));p.setBackground(Color.WHITE);p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(TemaCxc.BORDER),BorderFactory.createEmptyBorder(15,16,15,16)));JLabel num=new JLabel(n);num.setFont(new Font("Tahoma",Font.BOLD,20));num.setForeground(new Color(105,110,117));JPanel text=new JPanel();text.setOpaque(false);text.setLayout(new BoxLayout(text,BoxLayout.Y_AXIS));JLabel t=new JLabel(title);t.setFont(new Font("Tahoma",Font.BOLD,14));t.setForeground(TemaCxc.TEXT);JLabel d=new JLabel("<html><div style='width:300px'>"+desc+"</div></html>");d.setFont(new Font("Tahoma",Font.PLAIN,11));d.setForeground(new Color(75,78,83));d.setBorder(BorderFactory.createEmptyBorder(6,0,0,0));text.add(t);text.add(d);p.add(num,BorderLayout.WEST);p.add(text,BorderLayout.CENTER);p.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));p.addMouseListener(new java.awt.event.MouseAdapter(){public void mouseClicked(java.awt.event.MouseEvent e){action.run();}public void mouseEntered(java.awt.event.MouseEvent e){p.setBackground(new Color(243,245,247));}public void mouseExited(java.awt.event.MouseEvent e){p.setBackground(Color.WHITE);}});return p;}
